"""Observe normal recommendation responses generated by the existing browser UI."""
import json,time
from urllib.parse import urlsplit

def work_card(payload,video_id):
    """Small native-share metadata from the actual recommendation work object."""
    def find(value):
        if isinstance(value,dict):
            if value.get('aweme_id')==video_id:return value
            for child in value.values():
                if isinstance(child,(dict,list)):
                    result=find(child)
                    if result:return result
        elif isinstance(value,list):
            for child in value:
                result=find(child)
                if result:return result
    work=find(payload) or {};author=work.get('author') or {}
    card={'itemId':video_id,'title':str(work.get('desc') or '')[:600],'authorName':str(author.get('nickname') or '')[:80]}
    for field,target in [('uid','authorUid'),('sec_uid','authorSecUid')]:
        if author.get(field):card[target]=str(author[field])
    urls=(work.get('video') or {}).get('cover',{}).get('url_list') or []
    if urls:
        u=urlsplit(urls[0])
        if u.scheme=='https' and any(u.hostname==d or (u.hostname or '').endswith('.'+d) for d in ('douyinpic.com','byteimg.com','douyincdn.com')):card['coverUrl']=urls[0]
    return card


def fetch(db,context,limit,page_override=None):
    from app.video_rounds import worker_page,no_comment_draft,auth_required
    from app.douyin_toolkit import normalize_items
    from app.douyin_content import remember
    page=page_override if page_override is not None else worker_page(context)
    no_comment_draft(page)
    payloads=[]
    def capture(response):
        path=urlsplit(response.url)
        # /module/feed/ belongs to Jingxuan and must never masquerade as the
        # account's short-video recommendation feed during route transitions.
        if path.hostname!='www.douyin.com' or path.path not in ('/aweme/v1/web/tab/feed/','/aweme/v2/web/tab/feed/'):return
        try:
            body=response.body()
            if response.status==200 and len(body)<=8000000:
                value=json.loads(body)
                if isinstance(value,dict) and value.get('status_code')==0:payloads.append(value)
        except Exception:pass
    page.on('response',capture)
    try:
        page.goto('https://www.douyin.com/',wait_until='domcontentloaded',timeout=15000)
        link=page.get_by_role('link',name='推荐',exact=True)
        link.wait_for(state='visible',timeout=8000)
        href=link.get_attribute('href')
        if not href or 'jingxuan' in href:return {'status':'unavailable','reason':'Normal recommendation entry not verified','automatic_retry':False}
        payloads.clear()
        link.click(timeout=5000)
        deadline=time.monotonic()+18
        while time.monotonic()<deadline:
            page.wait_for_timeout(300)
            if auth_required(page):return {'status':'needs_verification','reason':'Manual verification required','automatic_retry':False}
            if payloads:break
        if 'jingxuan' in page.url:return {'status':'unavailable','reason':'Page remained in curated channel','automatic_retry':False}
        items=[];seen=set()
        for payload in payloads:
            remember(db,payload)
            for item in normalize_items(payload,limit):
                if item['video_id'] in seen or db.execute('SELECT 1 FROM video_reviews WHERE video_id=?',(item['video_id'],)).fetchone():continue
                seen.add(item['video_id']);item['source']='account_recommendation';item['work_card']=work_card(payload,item['video_id']);items.append(item)
        return {'status':'done' if items else 'unavailable','items':items[:limit],'source':'account_recommendation','page_url':page.url.split('?')[0],'reason':None if items else 'No verified recommendation response; no search fallback','automatic_retry':False}
    finally:page.remove_listener('response',capture)
